import "./CategoryCard.css";

function CategoryCard({ category }) {
  return (
    <div className="card">
      <img src={category.image} alt={category.name} />
      <div className="info">
        <h4>{category.name}</h4>
        <p>{category.items} items</p>
      </div>
    </div>
  );
}

export default CategoryCard;
